16	type DB struct {
17		db      *sql.DB
18		profile *profile.Profile
19	}
20	
21	func NewDB(profile *profile.Profile) (store.Driver, error) {
22		if profile == nil {
23			return nil, errors.New("profile is nil")
24		}
25	
26		// Open the PostgreSQL connection
27		db, err := sql.Open("postgres", profile.DSN)
28		if err != nil {
29			log.Printf("Failed to open database: %s", err)
30			return nil, errors.Wrapf(err, "failed to open database: %s", profile.DSN)
31		}
32	
33		var driver store.Driver = &DB{
34			db:      db,
35			profile: profile,
36		}
37	
38		// Return the DB struct
39		return driver, nil
40	}
41	
42	func (d *DB) GetDB() *sql.DB {
43		return d.db
44	}
45	
46	func (d *DB) Close() error {
47		return d.db.Close()
48	}
49	
50	func (d *DB) IsInitialized(ctx context.Context) (bool, error) {
51		var exists bool
52		err := d.db.QueryRowContext(ctx, "SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_catalog = current_database() AND table_name = 'memo' AND table_type = 'BASE TABLE')").Scan(&exists)
53		if err != nil {
54			return false, errors.Wrap(err, "failed to check if database is initialized")
55		}
56		return exists, nil
57	}
58	
59	// GetDatabaseSize returns the database size in bytes, or -1 if unavailable.
60	func (d *DB) GetDatabaseSize(ctx context.Context) (int64, error) {
61		var size int64
62		const q = `SELECT pg_database_size(current_database())`
63		if err := d.db.QueryRowContext(ctx, q).Scan(&size); err != nil {
64			return -1, errors.Wrap(err, "failed to query postgres database size")
65		}
66		return size, nil
67	}
